import{_ as i,c as a,o as t,ag as o}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Social-media-fatigue","description":"","frontmatter":{"title":"Social-media-fatigue"},"headers":[],"relativePath":"general/social-media-fatigue.md","filePath":"general/social-media-fatigue.md","lastUpdated":null}'),s={name:"general/social-media-fatigue.md"};function n(l,e,r,d,c,m){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="social-media-fatigue" tabindex="-1">Social-media-fatigue <a class="header-anchor" href="#social-media-fatigue" aria-label="Permalink to &quot;Social-media-fatigue&quot;">​</a></h1><h2 id="social-media-fatigue-smf" tabindex="-1">Social Media Fatigue (SMF) <a class="header-anchor" href="#social-media-fatigue-smf" aria-label="Permalink to &quot;Social Media Fatigue (SMF)&quot;">​</a></h2><p>BLUF: An interesting study looks at Social Media Fatigue (SMF) and narcissism and how they relate to the spread of misinformation. The study focuses on Asian countries (China, Singapore, Indonesia, Malaysia, Philippines, Thailand, and Vietnam) and sheds light on cultural differences.</p><p>The results suggest that social media fatigue can influence false beliefs of misinformation, which translates into sharing on social media. We also find that those with high levels of cognitive ability are less likely to believe and share misinformation. However, those with low cognitive ability and high levels of narcissism are most likely to share misinformation on social media due to social media fatigue. This study is one of the first to provide cross-national comparative evidence highlighting the adverse effects of social media fatigue on misinformation propagation and establishing that the relationship is not universal but dependent on both cognitive and dark personality traits of individuals.</p><p>References:</p><p>Ahmed, S., &amp; Rasul, M. E. (2023). Examining the association between social media fatigue, cognitive ability, narcissism, and misinformation sharing: Cross-national evidence from eight countries. <em>Scientific Reports</em>, <em>13</em>(1), Article 1. <a href="https://doi.org/10.1038/s41598-023-42614-z" target="_blank" rel="noreferrer">https://doi.org/10.1038/s41598-023-42614-z</a></p>',6)])])}const g=i(s,[["render",n]]);export{h as __pageData,g as default};
